ng // 'SEED', 'CROP', 'FERTILIZER', 'TOOL', 'ANIMAL', 'FOOD', 'ANIMAL_PRODUCT'\n\n  // Economia\n  buyPrice  Int @default(0) // Custo para comprar na loja\n  sellPrice Int @default(0) // Valor de venda\n  minLevel  Int @default(1) // Nível necessário para comprar/usar\n\n  // Atributos específicos para cultivo (quando type == 'SEED')\n  growthTime    Int? // Tempo em segundos\n  xpReward      Int? // XP concedido ao colher\n  yieldItemSlug String? // Slug do fruto que essa semente gera (ex: 'wheat')\n\n  // Atributos específicos para animais (quando type == 'ANIMAL')\n  productionTime Int? // Tempo para produzir após ser alimentado (segundos)\n  foodSlug       String? // Comida que consome (ex: 'chicken_feed')\n  foodQuantity   Int? // Quantidade de comida por alimentação\n  maxWeight      Int? // Peso máximo para venda (apenas porcos)\n  weightGain     Int? // Quanto ganha por alimentação (apenas porcos)\n\n  inventoryItems InventoryItem[]\n  plots          Plot[]          @relation(\"PlotToCrop\")\n  animals        Animal[]        @relation(\"AnimalToAnimal\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"items\")\n}\n\nmodel ActivityLog {\n  id          String   @id @default(cuid())\n  userId      String\n  action      String // 'plant', 'harvest', 'unlock_plot', 'level_up'\n  description String // \"Lucas plantou Cenoura no Plot 3\"\n  metadata    Json? // Dados adicionais: { cropSlug: \"carrot\", plotIndex: 3, coins: 50 }\n  createdAt   DateTime @default(now())\n\n  @@index([userId, createdAt])\n  @@index([createdAt])\n  @@map(\"activity_logs\")\n}\n\nmodel Animal {\n  id         String    @id @default(cuid())\n  profileId  String\n  animalSlug String // 'chicken', 'pig', 'cow'\n  fedAt      DateTime? // Última vez que foi alimentado\n  weight     Int? // Peso atual (apenas para porcos, kg)\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  profile Profile @relation(fields: [profileId], refere